import os
import requests

def query_metric_datapoints(metric_name, start_timestamp, end_timestamp):
    api_key = os.getenv("DATADOG_API_KEY")
    app_key = os.getenv("DATADOG_APP_KEY")

    if not api_key or not app_key:
        raise EnvironmentError("DATADOG_API_KEY and DATADOG_APP_KEY environment variables must be set.")

    endpoint = "https://api.datadoghq.com/api/v1/query"
    headers = {
        "Content-Type": "application/json",
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key
    }

    payload = {
        "query": f"avg:{metric_name}{{*}}",
        "from": int(start_timestamp),
        "to": int(end_timestamp)
    }

    response = requests.post(endpoint, headers=headers, json=payload)
    response.raise_for_status()

    result = response.json()
    datapoints = []

    for series in result.get("series", []):
        for ts, value in series.get("pointlist", []):
            if value is not None:
                datapoints.append((int(ts), float(value)))

    return sorted(datapoints, key=lambda x: x[0])
